import { useState, useEffect } from 'react';
import axios from 'axios';

const Brand = () => {
  const [brands, setBrands] = useState([]);
  const [name, setName] = useState('');
  const [image, setImage] = useState(null);
  const [searchTerm, setSearchTerm] = useState('');
  const role = localStorage.getItem("role"); // 'admin' or 'user'

  useEffect(() => {
    fetchBrands();
  }, []);

  const fetchBrands = async () => {
    try {
      const response = await axios.get('http://localhost:5000/api/users/allbrands');
      setBrands(response.data);
    } catch (error) {
      console.error("Error fetching brands:", error);
    }
  };

  const handleAddBrands = async (e) => {
    e.preventDefault();
    const formData = new FormData();
    formData.append("name", name);
    formData.append("image", image);
    try {
      const response = await axios.post('http://localhost:5000/api/users/addbrand', formData, {
        headers: { "Content-Type": "multipart/form-data" }
      });
      setName('');
      setImage(null);
      fetchBrands();
    } catch (error) {
      console.error("Error adding brand:", error);
    }
  };

  return (
    <div style={styles.page}>
      <div style={styles.leftSection}>
        <h1 style={styles.mainTitle}>🏷️ Brand Management</h1>
        <input
          type="text"
          placeholder="🔍 Search brands..."
          value={searchTerm}
          onChange={(e) => setSearchTerm(e.target.value)}
          style={styles.searchInput}
        />
        <div style={styles.grid}>
          {brands
            .filter((cat) => cat.name.toLowerCase().includes(searchTerm.toLowerCase()))
            .map((cat) => (
              <div
                key={cat._id}
                style={styles.card}
                onMouseOver={(e) => e.currentTarget.style.transform = "scale(1.04)"}
                onMouseOut={(e) => e.currentTarget.style.transform = "scale(1)"}
              >
                <img
                  src={`http://localhost:5000/uploads/${cat.image}`}
                  alt={cat.name}
                  style={styles.image}
                />
                <div style={styles.cardContent}>
                  <h3 style={styles.cardTitle}>{cat.name}</h3>
                </div>
              </div>
            ))}
        </div>
      </div>
      {role === "admin" && (
      <div style={styles.rightForm}>
        <h2 style={styles.formTitle}>✨ Add Brand</h2>
        <form onSubmit={handleAddBrands} encType="multipart/form-data" style={styles.form}>
          <input
            type="text"
            placeholder="Enter Brand Name"
            value={name}
            onChange={(e) => setName(e.target.value)}
            required
            style={styles.input}
          />
          <input
            type="file"
            accept="image/*"
            onChange={(e) => setImage(e.target.files[0])}
            required
            style={styles.input}
          />
          <button type="submit" style={styles.button}>➕ Add</button>
        </form>
      </div>
      )}
    </div>
  );
};

const styles = {
  page: {
    display: "grid",
    gridTemplateColumns: "1fr 300px",
    gap: "40px",
    padding: "40px",
    fontFamily: "'Segoe UI', sans-serif",
    background: "linear-gradient(to right, #f8f9fa, #e0eafc)",
    minHeight: "100vh",
  },
  leftSection: {
    width: "100%",
  },
  mainTitle: {
    fontSize: "32px",
    marginBottom: "20px",
    color: "#222",
  },
  searchInput: {
    width: "100%",
    padding: "12px",
    fontSize: "16px",
    borderRadius: "8px",
    border: "1px solid #ccc",
    marginBottom: "30px",
    boxShadow: "0 2px 5px rgba(0,0,0,0.05)",
  },
  grid: {
    display: "grid",
    gridTemplateColumns: "repeat(auto-fill, minmax(220px, 1fr))",
    gap: "24px",
  },
  card: {
    backgroundColor: "#fff",
    borderRadius: "12px",
    overflow: "hidden",
    boxShadow: "0 8px 18px rgba(0, 0, 0, 0.06)",
    transition: "transform 0.3s ease",
    cursor: "pointer",
  },
  image: {
    width: "100%",
    height: "160px",
    objectFit: "cover",
  },
  cardContent: {
    padding: "14px",
    textAlign: "center",
    backgroundColor: "#f1f5f9",
  },
  cardTitle: {
    margin: 0,
    fontSize: "18px",
    color: "#333",
    fontWeight: "600",
  },
  rightForm: {
    backgroundColor: "#ffffff",
    borderRadius: "14px",
    padding: "25px",
    boxShadow: "0 12px 24px rgba(0,0,0,0.08)",
    position: "sticky",
    top: "100px",
    height: "fit-content",
  },
  formTitle: {
    fontSize: "22px",
    marginBottom: "20px",
    color: "#222",
  },
  form: {
    display: "flex",
    flexDirection: "column",
    gap: "15px",
  },
  input: {
    padding: "12px",
    fontSize: "15px",
    borderRadius: "8px",
    border: "1px solid #bbb",
    backgroundColor: "#fdfdfd",
  },
  button: {
    padding: "12px",
    background: "linear-gradient(to right, #00b09b, #96c93d)",
    color: "white",
    fontSize: "16px",
    fontWeight: "bold",
    border: "none",
    borderRadius: "8px",
    cursor: "pointer",
    transition: "opacity 0.3s ease",
  },
};

export default Brand;
